import'package:flutter/material.dart';import'../services/funzi_api.dart';import'../services/funzi_data.dart';
class LeaderboardPage extends StatelessWidget{const LeaderboardPage({super.key});@override Widget build(BuildContext c)=>StreamBuilder(stream:FunziData.leaderboard(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(padding:const EdgeInsets.all(20),children:[Text('Improvement league',style:Theme.of(c).textTheme.headlineMedium),...s.data!.docs.asMap().entries.map((e)=>ListTile(leading:Text('#${e.key+1}'),title:const Text('Learner'),trailing:Text("${e.value.data()['improvementScore']??0}")))]);});}
class PortfolioParityPage extends StatefulWidget{const PortfolioParityPage({super.key});@override State<PortfolioParityPage>createState()=>_PortfolioParityPageState();}
class _PortfolioParityPageState extends State<PortfolioParityPage>{final title=TextEditingController(),reflection=TextEditingController();String status='';Future<void>submit()async{await FunziApi.submitPortfolio({'title':title.text,'reflection':reflection.text,'skillIds':[],'competencyIds':[],'artifactRefs':[]});setState(()=>status='Evidence saved for teacher review.');}@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(20),children:[Text('CBE competency portfolio',style:Theme.of(c).textTheme.headlineMedium),TextField(controller:title,decoration:const InputDecoration(labelText:'Evidence title')),TextField(controller:reflection,maxLines:4,decoration:const InputDecoration(labelText:'Reflection')),FilledButton(onPressed:title.text.isEmpty?null:submit,child:const Text('Submit evidence')),if(status.isNotEmpty)Text(status),const Divider(),StreamBuilder(stream:FunziData.portfolio(),builder:(c,s)=>s.hasData?Column(children:s.data!.docs.map((d)=>ListTile(title:Text("${d.data()['title']??'Evidence'}"),subtitle:Text(d.data()['teacherVerified']==true?'Teacher verified':'Awaiting review'))).toList()):const CircularProgressIndicator())]);}}
class GeneratedSciencePage extends StatefulWidget{final String skillId;const GeneratedSciencePage(this.skillId,{super.key});@override State<GeneratedSciencePage>createState()=>_GeneratedSciencePageState();}
class _GeneratedSciencePageState extends State<GeneratedSciencePage>{final topic=TextEditingController(text:'How changing a variable affects the measured result');Map<String,dynamic>?sim;bool busy=false;@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(20),children:[Text('Virtual Science Lab',style:Theme.of(c).textTheme.headlineMedium),TextField(controller:topic,decoration:const InputDecoration(labelText:'Experiment topic')),FilledButton(onPressed:busy?null:()async{setState(()=>busy=true);try{final r=await FunziApi.scienceSimulation(widget.skillId,topic.text);setState(()=>sim=r);}finally{setState(()=>busy=false);}},child:const Text('Create simulation')),if(sim!=null)Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text("${sim!['title']}",style:Theme.of(c).textTheme.titleLarge),Text("${sim!['objective']}"),Text('Safety: ${sim!['safety']??[]}'),const SizedBox(height:8),const Text('Generated experiment schema is shared with the React client. Deterministic solver canvases are available in the dedicated Flutter science workspace.')])))]);}